  941: /// Ping and keep-alive are ordinary opcodes handled on the world thread, so latency, the
  942: /// overspeed policy and an account's security level stay on the game side of the seam.
  943: void WorldSession::HandlePingOpcode(WorldPacket& recvPacket)
  944: {
  945:     // 4.3.4 sends the latency FIRST and the sequence second.
  946:     //
  947:     // On the wire, one client sitting still (world-packets.log, two sessions):
  948:     //
  949:     //     CMSG_PING  00 00 00 00 | 01 00 00 00
  950:     //     CMSG_PING  00 00 00 00 | 02 00 00 00
  951:     //     CMSG_PING  00 00 00 00 | 03 00 00 00
  952:     //
  953:     // The second dword counts; the first never moves. The counter is the
  954:     // sequence the client waits to see echoed, and the other field is the
  955:     // latency it reports. Read the other way round, the sequence lands in the
  956:     // latency and the latency is echoed as the sequence.
  957:     //
  958:     // Nothing in the packet distinguishes the two fields by shape: both are
  959:     // uint32, and a wrong guess is only visible as a number that never rises.
  960:     uint32 latency = 0;
  961:     uint32 ping = 0;
  962:     recvPacket >> latency;
  963:     recvPacket >> ping;
  964: 
  965:     uint32 fastPingRun =
  966:         m_pingTracker.Record(SessionPingTracker::Clock::now());
  967:     uint32 maximum =
  968:         sGameConfig.getConfig(CONFIG_UINT32_MAX_OVERSPEED_PINGS);
  969:     if (m_pingTracker.ShouldKick(maximum, GetSecurity() == SEC_PLAYER))
  970:     {
  971:         sLog.outError(
  972:             "WorldSession::HandlePingOpcode: account %u kicked for "
  973:             "overspeeded pings (%u in a row), address = %s",
  974:             GetAccountId(), fastPingRun, GetRemoteAddress().c_str());
  975:         KickPlayer();
  976:         return;
  977:     }
  978: 
  979:     // Against the wire it came in on: the client measures the two streams
  980:     // independently and shows both.
  981:     const proto::LinkSlot stream =
  982:         recvPacket.HasStream() ? recvPacket.GetStream() : proto::LinkSlot::Zero;
  983: 
  984:     SetLatency(stream, latency);
  985: 
  986:     // Echo the sequence, not the latency: the client matches a pong to the
  987:     // ping it answers by this value alone, and drops one it cannot place.
  988:     WorldPacket response(SMSG_PONG, 4);
  989: 
  990:     // Back down the wire it came up. The client pings both streams, counts
  991:     // each one separately, and only matches a pong against the counter of the
  992:     // connection it arrives on -- so answering everything on stream 0 left the
  993:     // World readout of GetNetStats() at zero however good the link was.
  994:     response.SetStream(stream);
  995: 
  996:     response << ping;
  997:     SendPacket(&response);
  998: }
